/* ---------------------------------------------------------
   STORAGE HELPERS
--------------------------------------------------------- */
async function loadEntry(day) {
  try {
    const res = await window.storage.get(`entry:${day}`, false);
    return res ? JSON.parse(res.value) : { ...EMPTY_ENTRY };
  } catch {
    return { ...EMPTY_ENTRY };
  }
}
async function saveEntryStorage(day, data) {
  try {
    await window.storage.set(`entry:${day}`, JSON.stringify(data), false);
    return true;
  } catch {
    return false;
  }
}
async function loadProgress() {
  try {
    const res = await window.storage.get("progress", false);
    return res ? JSON.parse(res.value) : { completedDays: [] };
  } catch {
    return { completedDays: [] };
  }
}
async function saveProgress(progress) {
  try {
    await window.storage.set("progress", JSON.stringify(progress), false);
  } catch {
    /* best effort */
  }
}

function computeStreaks(completedDays) {
  const set = new Set(completedDays);
  let longest = 0, run = 0;
  for (let d = 1; d <= 90; d++) {
    if (set.has(d)) { run += 1; longest = Math.max(longest, run); } else { run = 0; }
  }
  // current streak = consecutive completed days ending at the most recently completed day
  let current = 0;
  if (completedDays.length) {
    const maxDay = Math.max(...completedDays);
    let d = maxDay;
    while (set.has(d)) { current += 1; d -= 1; }
  }
  return { current, longest };
}

