/* The woodpile — signature progress element: 90 log-rounds stacked 10-wide */
function Woodpile({ completedDays, currentDay, onJump }) {
  const set = new Set(completedDays);
  const rows = [];
  for (let r = 0; r < 9; r++) rows.push(Array.from({ length: 10 }, (_, i) => r * 10 + i + 1));
  return (
    <div style={styles.woodpileWrap}>
      {rows.map((row, ri) => (
        <div key={ri} style={styles.woodpileRow}>
          {row.map((d) => {
            const done = set.has(d);
            const active = d === currentDay;
            return (
              <button
                key={d}
                onClick={() => onJump(d)}
                title={`Day ${d}`}
                style={{
                  ...styles.log,
                  background: done
                    ? "radial-gradient(circle at 35% 35%, #7C4A2D, #4B2D18 72%)"
                    : "radial-gradient(circle at 35% 35%, #3A322A, #221C17 72%)",
                  borderColor: active ? "#B4552F" : done ? "#A8703F" : "#4A3F35",
                  boxShadow: active ? "0 0 0 2px #B4552F55" : "none",
                }}
              >
                {done ? (
                  <svg width="9" height="9" viewBox="0 0 12 10" fill="none">
                    <path d="M1 5L4.5 8.5L11 1" stroke="#EDE6D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                ) : (
                  <span style={{ fontSize: 8, color: "#7A7166", fontFamily: "'IBM Plex Mono', monospace" }}>{d}</span>
                )}
              </button>
            );
          })}
        </div>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------
   MAIN APP
--------------------------------------------------------- */
export default function Timberline() {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [day, setDay] = useState(1);
  const [entry, setEntry] = useState(EMPTY_ENTRY);
  const [progress, setProgress] = useState({ completedDays: [] });
  const [view, setView] = useState("journal"); // journal | progress
  const [cardsOpen, setCardsOpen] = useState(false);
  const [savedFlash, setSavedFlash] = useState(false);

  useEffect(() => {
    (async () => {
      const p = await loadProgress();
      setProgress(p);
      const startDay = p.completedDays && p.completedDays.length
        ? Math.min(Math.max(...p.completedDays) + 1, 90)
        : 1;
      setDay(startDay);
      const e = await loadEntry(startDay);
      setEntry(e);
      setLoading(false);
    })();
  }, []);

  const switchDay = useCallback(async (n) => {
    const clamped = Math.min(90, Math.max(1, n));
    setLoading(true);
    const e = await loadEntry(clamped);
    setEntry(e);
    setDay(clamped);
    setLoading(false);
  }, []);

  const persist = useCallback(async (nextEntry) => {
    setEntry(nextEntry);
    setSaving(true);
    await saveEntryStorage(day, nextEntry);
    setSaving(false);
  }, [day]);

  const updateField = (field, value) => persist({ ...entry, [field]: value });
  const updateGratitude = (idx, value) => {
    const g = [...entry.gratitude];
    g[idx] = value;
    persist({ ...entry, gratitude: g });
  };
  const toggleDopamine = (key) => persist({ ...entry, dopamine: { ...entry.dopamine, [key]: !entry.dopamine[key] } });
  const toggleOps = (key) => persist({ ...entry, ops: { ...entry.ops, [key]: !entry.ops[key] } });

  const markComplete = async () => {
    const next = { ...entry, completed: !entry.completed };
    await persist(next);
    let days = new Set(progress.completedDays || []);
    if (next.completed) days.add(day); else days.delete(day);
    const arr = Array.from(days).sort((a, b) => a - b);
    const newProgress = { completedDays: arr };
    setProgress(newProgress);
    await saveProgress(newProgress);
    if (next.completed) {
      setSavedFlash(true);
      setTimeout(() => setSavedFlash(false), 1600);
    }
  };

  const reading = READING_PLAN[day - 1];
  const phase = phaseFor(day);
  const { current: currentStreak, longest: longestStreak } = useMemo(
    () => computeStreaks(progress.completedDays || []),
    [progress.completedDays]
  );
  const pct = Math.round(((progress.completedDays || []).length / 90) * 100);

  if (loading && day === 1 && !entry) {
    return <div style={styles.loadingScreen}>Loading Timberline…</div>;
  }

  return (
    <div style={styles.app}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Libre+Baskerville:ital@0;1&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
        * { box-sizing: border-box; }
        textarea, input { font-family: 'Libre Baskerville', serif; }
        ::placeholder { color: #8A7A6390; }
        button { cursor: pointer; font-family: inherit; }
      `}</style>

      {/* HEADER */}
      <div style={styles.header}>
        <Plaid />
        <div style={styles.headerInner}>
          <div style={styles.brandRow}>
            <img src={IMG_BADGE} alt="" style={styles.axeMark} />
            <div>
              <div style={styles.brandTitle}>TIMBERLINE</div>
              <div style={styles.brandSub}>A 90-DAY WALK OUT OF THE FOG</div>
            </div>
          </div>
          <div style={styles.streakBadge}>
            <span style={styles.streakFlame}>{"🔥"}</span>
            <div>
              <div style={styles.streakNum}>{currentStreak}</div>
              <div style={styles.streakLbl}>day streak</div>
            </div>
          </div>
        </div>
      </div>

      {/* TAB NAV */}
      <div style={styles.tabRow}>
        <button onClick={() => setView("journal")} style={{ ...styles.tab, ...(view === "journal" ? styles.tabActive : {}) }}>
          Today's Entry
        </button>
        <button onClick={() => setView("progress")} style={{ ...styles.tab, ...(view === "progress" ? styles.tabActive : {}) }}>
          The Woodpile
        </button>
        <button onClick={() => setCardsOpen((v) => !v)} style={{ ...styles.tab, ...(cardsOpen ? styles.tabActive : {}) }}>
          Field Cards
        </button>
      </div>

      {/* FIELD CARDS PANEL */}
      {cardsOpen && (
        <div style={styles.cardsPanel}>
          <div style={styles.cardsGrid}>
            {POCKET_CARDS.map((c) => (
              <div key={c.id} style={{ ...styles.pocketCard, borderColor: c.accent }}>
                <div style={{ ...styles.pocketCardLabel, background: c.accent }}>{c.label}</div>
                <div style={styles.pocketVerse}>{c.verse}</div>
                <div style={styles.pocketRef}>{c.ref}</div>
                <ol style={styles.pocketSteps}>
                  {c.steps.map((s, i) => <li key={i}>{s}</li>)}
                </ol>
              </div>
            ))}
          </div>
          <div style={styles.resetTableWrap}>
            <div style={styles.resetTableTitle}>QUICK RESET REFERENCE</div>
            <table style={styles.resetTable}>
              <tbody>
                {RESET_TABLE.map((r, i) => (
                  <tr key={i} style={{ borderTop: i ? "1px solid #4A3F3550" : "none" }}>
                    <td style={styles.resetTd}>{r.trigger}</td>
                    <td style={{ ...styles.resetTd, color: "#C9A876" }}>{r.protocol}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* JOURNAL VIEW */}
      {view === "journal" && (
        <div style={styles.main}>
          {/* Day nav */}
          <div style={styles.dayNav}>
            <button onClick={() => switchDay(day - 1)} disabled={day <= 1} style={styles.navBtn}>{"‹"}</button>
            <div style={styles.dayNavCenter}>
              <div style={{ ...styles.phaseTag, background: phase.color }}>{phase.name.toUpperCase()}</div>
              <div style={styles.dayTitle}>DAY {day} <span style={styles.dayOf}>/ 90</span></div>
              <input
                type="range" min={1} max={90} value={day}
                onChange={(e) => switchDay(Number(e.target.value))}
                style={styles.slider}
              />
            </div>
            <button onClick={() => switchDay(day + 1)} disabled={day >= 90} style={styles.navBtn}>{"›"}</button>
          </div>

          {loading ? (
            <div style={styles.loadingScreen}>Loading day {day}…</div>
          ) : (
            <>
              {/* Reading */}
              <div style={styles.readingCard}>
                <div style={styles.readingLabel}>TODAY'S READING</div>
                <div style={styles.readingRef}>{reading.ref}</div>
                <div style={styles.readingTheme}>{reading.theme}</div>
              </div>

              {/* Morning Anchor */}
              <div style={styles.card}>
                <SectionHeader n="I" title="Morning Anchor" sub="Prayer, gratitude, scripture" />
                <label style={styles.fieldLabel}>Surrender prayer for today</label>
                <textarea
                  value={entry.prayer}
                  onChange={(e) => updateField("prayer", e.target.value)}
                  placeholder="Lord, I give You my mind, body, and will today…"
                  style={styles.textarea}
                  rows={2}
                />
                <label style={styles.fieldLabel}>Three concrete things I'm grateful for</label>
                {entry.gratitude.map((g, i) => (
                  <input
                    key={i}
                    value={g}
                    onChange={(e) => updateGratitude(i, e.target.value)}
                    placeholder={`${i + 1}.`}
                    style={styles.input}
                  />
                ))}
                <label style={styles.fieldLabel}>What stood out in {reading.ref}?</label>
                <textarea
                  value={entry.verseNote}
                  onChange={(e) => updateField("verseNote", e.target.value)}
                  placeholder="The word or verse that hit hardest today…"
                  style={styles.textarea}
                  rows={2}
                />
                <label style={styles.fieldLabel}>How I'll apply it today</label>
                <textarea
                  value={entry.application}
                  onChange={(e) => updateField("application", e.target.value)}
                  style={styles.textarea}
                  rows={2}
                />
              </div>

              {/* Dopamine reset */}
              <div style={styles.card}>
                <SectionHeader n="II" title="Natural Reset Habits" sub="Rebuilding baseline, no chemical crash" />
                {DOPAMINE_ITEMS.map((item) => (
                  <Checkbox key={item.key} checked={!!entry.dopamine[item.key]} onChange={() => toggleDopamine(item.key)} label={item.label} />
                ))}
              </div>

              {/* Ops tasks */}
              <div style={styles.card}>
                <SectionHeader n="III" title="Staying Ordered" sub="Small operational wins" />
                {OPS_ITEMS.map((item) => (
                  <Checkbox key={item.key} checked={!!entry.ops[item.key]} onChange={() => toggleOps(item.key)} label={item.label} />
                ))}
              </div>

              {/* Evening */}
              <div style={styles.card}>
                <SectionHeader n="IV" title="Evening Reflection" sub="Close the day out honest" />
                <label style={styles.fieldLabel}>Where did I see strength today?</label>
                <textarea
                  value={entry.godMoment}
                  onChange={(e) => updateField("godMoment", e.target.value)}
                  style={styles.textarea}
                  rows={2}
                />
                <label style={styles.fieldLabel}>Did a craving or temptation show up? How'd I handle it?</label>
                <textarea
                  value={entry.cravingLog}
                  onChange={(e) => updateField("cravingLog", e.target.value)}
                  style={styles.textarea}
                  rows={2}
                />
                <label style={styles.fieldLabel}>Tomorrow's #1 focus</label>
                <input
                  value={entry.tomorrowFocus}
                  onChange={(e) => updateField("tomorrowFocus", e.target.value)}
                  style={styles.input}
                />
              </div>

              {/* Complete button */}
              <button onClick={markComplete} style={{ ...styles.completeBtn, ...(entry.completed ? styles.completeBtnDone : {}) }}>
                {entry.completed ? "✓  DAY MARKED COMPLETE" : "MARK DAY COMPLETE"}
              </button>
              <div style={styles.saveHint}>{saving ? "saving…" : " "}</div>
            </>
          )}
        </div>
      )}

      {/* PROGRESS VIEW */}
      {view === "progress" && (
        <div style={styles.main}>
          <div style={styles.statsRow}>
            <div style={styles.statBox}>
              <div style={styles.statNum}>{(progress.completedDays || []).length}</div>
              <div style={styles.statLbl}>DAYS LOGGED</div>
            </div>
            <div style={styles.statBox}>
              <div style={styles.statNum}>{currentStreak}</div>
              <div style={styles.statLbl}>CURRENT STREAK</div>
            </div>
            <div style={styles.statBox}>
              <div style={styles.statNum}>{longestStreak}</div>
              <div style={styles.statLbl}>LONGEST STREAK</div>
            </div>
            <div style={styles.statBox}>
              <div style={styles.statNum}>{pct}%</div>
              <div style={styles.statLbl}>OF 90 DAYS</div>
            </div>
          </div>

          <div style={styles.progressBarOuter}>
            <div style={{ ...styles.progressBarInner, width: `${pct}%` }} />
          </div>

          <img src={IMG_WOODPILE_DECO} alt="" style={styles.woodpileDeco} />
          <div style={styles.woodpileTitle}>THE WOODPILE - one round per day, tap to jump</div>
          <div style={styles.woodpileLegend}>
            <span><i style={{ ...styles.legendDot, background: "#7C4A2D" }} /> split</span>
            <span><i style={{ ...styles.legendDot, background: "#2A2420" }} /> uncut</span>
          </div>
          <Woodpile completedDays={progress.completedDays || []} currentDay={day} onJump={(d) => { switchDay(d); setView("journal"); }} />

          {PHASES.map((p) => {
            const inPhase = (progress.completedDays || []).filter((d) => d >= p.range[0] && d <= p.range[1]).length;
            return (
              <div key={p.name} style={styles.phaseRow}>
                <div style={{ ...styles.phaseDot, background: p.color }} />
                <div style={styles.phaseRowText}>
                  <div style={styles.phaseRowTitle}>{p.name}</div>
                  <div style={styles.phaseRowSub}>{p.sub} - {inPhase}/30 days</div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {savedFlash && (
        <div style={styles.toast}>Logged. Keep walking.</div>
      )}

      <img src={IMG_FOOTER_AXE} alt="" style={styles.footerImg} />
      <div style={styles.footer}>"He restores my soul. He leads me in paths of righteousness for His name's sake." - Psalm 23:3</div>
    </div>
  );
}

